def unpack(payload: str) -> bytes:
    return zlib.decompress(base64.b85decode(payload.encode("ascii")))


def main() -> None:
    root = Path(__file__).resolve().parents[1]
    source = root / "data/course_redevelopment/biomecanica-medios-continuos/units/unit-01.json"
    mirror = root / "data/generated_units/biomecanica-medios-continuos/unit-01.json"
    test = root / "tests/test_biomecanica_medios_continuos_unit_01_curated.py"
    unit_bytes = unpack(UNIT)
    source.write_bytes(unit_bytes)
    mirror.write_bytes(unit_bytes)
    test.write_bytes(unpack(TEST))
    assert source.read_bytes() == mirror.read_bytes()
    assert b"Concepto de la unidad que debe definirse" not in unit_bytes


if __name__ == "__main__":
    main()
